  const full = data.inAnki && data.calendar && AF.calendarFull(data.calendar);
  const wider = full || (typeof want === 'number' && want > data.maxWidth);
  root.style.maxWidth = full ? 'none' : Math.max(data.maxWidth, wider ? want : 0) + pad + 'px';
