    const px = x + 0.5, py = y + 0.5; let best = -9;
    for (const b of blobs) { const nx = (px - b.x) / b.sx, ny = (py - b.y) / b.sy; if (nx * nx + ny * ny <= 1) best = Math.max(best, -(nx * 0.6 + ny * 0.8)); }
