    if (Math.abs(x - cx) >= w * 0.34) continue;
    let low = -1; for (let y = 0; y < H; y++) if (tone[y * W + x] >= 0) low = y;
    if (low < 2) continue;
    if (tone[(low - 1) * W + x] >= 0) tone[(low - 1) * W + x] = 1;
