    if (at < reach && burn >= EMBERS_FROM && hashStr('ember,' + x + ',' + y + ',' + seed) / 4294967296 < EMBERS * burn) c = EMBER[(x + y) & 1];
    d[i] = c[0]; d[i + 1] = c[1]; d[i + 2] = c[2];
