        if (hole && R() < hole) continue;
        const l = -(dx / hw) * 0.6 + (y === yT ? 0.55 : y === yB ? -0.5 : 0) + (R() - 0.5) * 0.22;
        tone[y * W + x] = l > 0.62 ? 4 : l > 0.14 ? 3 : l > -0.35 ? 2 : 1;
