  for (const px of [tx - 1, tx + tw2]) { rect(px, tTop - 4, px, tTop - 1, M.SPIRE, px < tx ? 2 : 1); set(px, tTop - 5, M.IRON); set(px, tTop - 6, M.IRON); }
