  const CB = Math.min(VE - 2, SB + 1);
  obj = CB;
  const cw = 25, ch = S(23), cTop = CB - ch;
  const car = { x: carX, top: cTop, w: cw, h: ch, pts: [], base: CB };
  const cone = Math.round(ch * 0.44), val = 2, plat = 2;
