    for (let x = x0; x <= x1; x += 2) set(x, ay - 1, M.BULB, 0);
    rect(x0 - 1, SB - 3, x1 + 1, SB - 3, M.WOOD, 2);
    rect(x0, SB - 2, x1, SB, M.WOOD, 0);
