  const skyAt = y => hex(th.sky[Math.max(0, Math.min(th.sky.length - 1, Math.floor(y / env.hor * th.sky.length)))]);
  const veil = w === 'fog' ? 0.5 : w === 'cloudy' ? 0.4 : w === 'snow' ? 0.35 : 0;
  const px = (c, x, y) => { g.fillStyle = rgb(c); g.fillRect(x, y, 1, 1); };
