const FROSTS = { dawn: H6(['#f8e2dc', '#d8c4cc']), golden_hour: H6(['#f8ecd0', '#d8ccb4']), dusk: H6(['#e8d8ec', '#bcb0cc']), night: H6(['#e2eafc', '#aebcdc']) };

