  const mouthRows = Array.isArray(F.m[0][0]) ? F.m[mouth ? 1 : 0] : F.m, all = F.e.concat(mouthRows);
  const maxR = Math.max(...all.map(f => f[0])), [, bh] = SIZE_WH[size];
  const shift = h > bh ? 1 : maxR > h - 2 ? h - 2 - maxR : 0;
